import json,csv,hashlib,glob,numpy as np
from pathlib import Path
b=Path('[local path omitted]'); geo=json.load(open(b/'gaia-geometry.json'))
for row in csv.DictReader(open(b/'queue.csv')):
 t=row['tic'];m=json.load(open(b/t/'measurements.json'));e=[x for x in m['events'] if x.get('timing_usable')]; n=np.array([x['cycle'] for x in e]); y=np.array([x['mid_btjd'] for x in e]); s=np.array([x['timing_error_days'] for x in e]); X=np.column_stack((np.ones(len(n)),n-n.min())); A=X/s[:,None]; z=y/s; p=np.linalg.lstsq(A,z,rcond=None)[0]; res=y-X@p; red=sum((res/s)**2)/(len(n)-2); cov=np.linalg.inv(A.T@A)*max(1,red); g=geo[t]; files=glob.glob('[local path omitted] 5/made/sb1-scale/diffimg/'+t+'/diff*.json'); files=glob.glob(str(b/t/'revised-cutout/diff*.json')) if t=='407207285' else files
 d=json.load(open(files[0])) if files else {}; poss=[q for q in d.get('neighbours_60',[]) if q.get('possible')]; h=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();
 print(t,'n',len(n),'P %.10f err %.8g epoch %.6f cycle %d rms %.5g red %.3g depth %.2f'%(p[1],np.sqrt(cov[1,1]),p[0],n.min(),np.std(res),red,np.median([x['depth_ppt'] for x in e])),'gaia',round(g['closest']['offset_days'],4),round(g['closest']['gaia_covariance_linear_error_days'],4),'dur',round(g['observed_duration_hours'],2),round(g['central_duration_hours_approx'],2),'pixel',d.get('deficit_minus_target_px'),'capable',[(q['source_id'],round(q['sep'],2),round(q['depth_needed'],3)) for q in poss], 'diff', files[0] if files else '-',h(files[0]) if files else '-', 'measure',h(b/t/'measurements.json'),'windows',h(b/t/'raw-windows.csv'))
